contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: optionally Put some value into c, then attempt Collect of some amount.
    // The invariant: for this caller (address(this)), c.Acc(address(this)).balance + address(c).balance
    // should not increase as a result of a Collect call; if Collect reverts then both observed values remain as before.

    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        require(true);
        // ensure we have enough balance to put
        if (putAmount > 0) {
            require(address(this).balance >= putAmount);
            // send Ether to c via Put
            c.Put{value: putAmount}(putUnlock);
        }

        // read before-values via public getters
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        bool reverted;
        // attempt Collect; it is payable in P but Collect uses msg.sender.call to send out funds
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule to assert:
        // - The contract's recorded per-address balance never increases as a result of Collect (it can only decrease or stay same),
        // - If Collect reverted then balances and unlockTime did not change.
        assert(
            // recorded balance never increases
            afterAccBal <= beforeAccBal
            // when reverted: both stored balance and contract balance unchanged and unlockTime unchanged
            && (reverted ? (afterAccBal == beforeAccBal && afterCbal == beforeCbal && afterUnlock == beforeUnlock) : true)
        );
    }

    receive() external payable { }
}

