contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes parameters to perform Put and then Collect; amountPut and amountCollect are in wei
    function run(uint unlockOffset, uint amountPut, uint amountCollect) public payable {
        require(address(this).balance >= amountPut, "not enough balance to fund Put");
        // initial observations
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put to deposit amountPut and set unlockTime to now+unlockOffset (if > block.timestamp inside contract)
        c.Put{value: amountPut}(block.timestamp + unlockOffset);

        // observe after put
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // attempt Collect of amountCollect and record whether it reverted
        bool reverted;
        try c.Collect(amountCollect) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // final observations
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // - If Collect did not revert then midBal >= amountCollect, midBal >= c.MinSum (we cannot read MinSum directly here except via public, so read it),
        //   and block.timestamp > midUnlock must have held; final balances decreased by exactly amountCollect.
        // - If Collect reverted then balances remained unchanged from immediately after Put.

        uint minSum = c.MinSum();

        // We cannot directly assert conditions about block.timestamp inside the checked contract invocation since it's dynamic,
        // but we can assert the observable invariants about balances and the revert flag:
        // If not reverted: afterBal == midBal - amountCollect AND afterContractBal == midContractBal - amountCollect
        // If reverted: afterBal == midBal AND afterContractBal == midContractBal

        assert(reverted
            ? (afterBal == midBal && afterContractBal == midContractBal)
            : (midBal >= amountCollect && midBal >= minSum && afterBal + amountCollect == midBal && afterContractBal + amountCollect == midContractBal)
        );
    }

    // allow receiving refunds
    receive() external payable {}
}

