contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will: put some funds into c for this contract's address, then attempt Collect and assert
    // that on successful Collect the stored balance for this address decreased by _am and the contract balance decreased appropriately.
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        require(putAmount > 0 && collectAmount > 0); // require some meaningful amounts
        // ensure this contract has enough Ether to fund the Put call
        require(address(this).balance >= putAmount);

        // Initially read observable values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Call Put to deposit funds and set unlock time (may update unlockTime to block.timestamp if putUnlock <= now)
        c.Put{value: putAmount}(putUnlock);

        // Read after-put values
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Preconditions for Collect success according to contract logic:
        // - midBal >= MinSum
        // - midBal >= collectAmount
        // - block.timestamp > midUnlock
        // We cannot modify block.timestamp, so make the assertion conditional on whether Collect would succeed.
        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-collect values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule: if Collect did not revert then the stored balance decreased by exactly collectAmount
        // and the contract's ETH balance decreased by at least collectAmount (since transfer may forward gas and succeed or revert;
        // but non-revert implies it succeeded so contract balance decreased by exactly collectAmount).
        // We express a safe observable relation: if not reverted then midBal = afterBal + collectAmount and midCbal >= afterCbal + collectAmount.
        assert(reverted || (midBal == afterBal + collectAmount && midCbal >= afterCbal + collectAmount));
    }

    receive() external payable { }
}
